    const line = installsBody.indexOf("id={noticeId}");
    const closes = installsBody.indexOf("</div>", line);
    const bar = Math.min(...["!can.install", "!can.update", "!can.remove", "!can.settings"].map((one) => installsBody.indexOf(one)));
